import { useMergedRefs } from "@base-ui/utils/useMergedRefs";
import type {
  Cell,
  ColumnPinningState,
  ColumnVisibilityState,
  Row,
  RowData,
} from "@tanstack/react-table";
import type { VirtualItem } from "@tanstack/react-virtual";
import { cn } from "cn";
import * as React from "react";
import { DataGridCell } from "@/registry/base/components/data-grid/data-grid-cell";
import type { DataGridFeatures } from "@/registry/base/lib/data-grid-features";
import type {
  CellPosition,
  DataGridTableMeta,
  Direction,
  RowHeightValue,
} from "@/registry/base/lib/data-grid-types";
import {
  flexRender,
  getCellKey,
  getColumnBorderVisibility,
  getColumnPinningStyle,
  getRowHeightValue,
} from "@/registry/base/lib/data-grid-utils";

interface DataGridRowProps<TData extends RowData>
  extends React.ComponentProps<"div"> {
  row: Row<DataGridFeatures, TData>;
  tableMeta: DataGridTableMeta;
  virtualItem: VirtualItem;
  measureElement: (node: Element | null) => void;
  rowMapRef: React.RefObject<Map<number, HTMLDivElement>>;
  rowHeight: RowHeightValue;
  columnVisibility: ColumnVisibilityState;
  columnPinning: ColumnPinningState;
  focusedCell: CellPosition | null;
  editingCell: CellPosition | null;
  cellSelectionKeys: Set<string>;
  searchMatchColumns: Set<string> | null;
  activeSearchMatch: CellPosition | null;
  dir: Direction;
  readOnlyColumnIds: Set<string>;
  stretchColumns: boolean;
  adjustLayout: boolean;
}

export const DataGridRow = React.memo(DataGridRowImpl, (prev, next) => {
  const rowId = next.row.id;

  // Re-render if row identity changed
  if (prev.row.id !== rowId) {
    return false;
  }

  // Re-render if the row moved, since the row map and aria-rowindex are positional
  if (prev.virtualItem.index !== next.virtualItem.index) {
    return false;
  }

  // Re-render if row data (original) reference changed
  if (prev.row.original !== next.row.original) {
    return false;
  }

  // Re-render if virtual position changed (handles transform updates)
  if (prev.virtualItem.start !== next.virtualItem.start) {
    return false;
  }

  // Re-render if focus state changed for this row
  const prevHasFocus = prev.focusedCell?.rowId === rowId;
  const nextHasFocus = next.focusedCell?.rowId === rowId;

  if (prevHasFocus !== nextHasFocus) {
    return false;
  }

  // Re-render if focused column changed within this row
  if (nextHasFocus && prevHasFocus) {
    if (prev.focusedCell?.columnId !== next.focusedCell?.columnId) {
      return false;
    }
  }

  // Re-render if editing state changed for this row
  const prevHasEditing = prev.editingCell?.rowId === rowId;
  const nextHasEditing = next.editingCell?.rowId === rowId;

  if (prevHasEditing !== nextHasEditing) {
    return false;
  }

  // Re-render if editing column changed within this row
  if (nextHasEditing && prevHasEditing) {
    if (prev.editingCell?.columnId !== next.editingCell?.columnId) {
      return false;
    }
  }

  // Re-render if this row's selected cells changed
  // Using stable Set reference that only includes this row's cells
  if (prev.cellSelectionKeys !== next.cellSelectionKeys) {
    return false;
  }

  // Re-render if column visibility changed
  if (prev.columnVisibility !== next.columnVisibility) {
    return false;
  }

  // Re-render if row height changed
  if (prev.rowHeight !== next.rowHeight) {
    return false;
  }

  // Re-render if column pinning state changed
  if (prev.columnPinning !== next.columnPinning) {
    return false;
  }

  // Re-render if table or column editing permissions changed
  if (prev.readOnlyColumnIds !== next.readOnlyColumnIds) {
    return false;
  }

  // Re-render if search match columns changed for this row
  if (prev.searchMatchColumns !== next.searchMatchColumns) {
    return false;
  }

  // Re-render if active search match changed for this row
  if (prev.activeSearchMatch?.columnId !== next.activeSearchMatch?.columnId) {
    return false;
  }

  // Re-render if direction changed
  if (prev.dir !== next.dir) {
    return false;
  }

  // Re-render if adjustLayout state changed
  if (prev.adjustLayout !== next.adjustLayout) {
    return false;
  }

  // Re-render if stretchColumns changed
  if (prev.stretchColumns !== next.stretchColumns) {
    return false;
  }

  // Skip re-render - props are equal
  return true;
}) as typeof DataGridRowImpl;

function DataGridRowImpl<TData extends RowData>({
  row,
  tableMeta,
  virtualItem,
  measureElement,
  rowMapRef,
  rowHeight,
  columnVisibility,
  columnPinning,
  focusedCell,
  editingCell,
  cellSelectionKeys,
  searchMatchColumns,
  activeSearchMatch,
  dir,
  readOnlyColumnIds,
  stretchColumns,
  adjustLayout,
  className,
  style,
  ref,
  ...props
}: DataGridRowProps<TData>) {
  const virtualRowIndex = virtualItem.index;
  const rowId = row.id;

  const onRowChange = React.useCallback(
    (node: HTMLDivElement | null) => {
      if (typeof virtualRowIndex === "undefined") return;

      if (node) {
        measureElement(node);
        rowMapRef.current?.set(virtualRowIndex, node);
      } else {
        rowMapRef.current?.delete(virtualRowIndex);
      }
    },
    [virtualRowIndex, measureElement, rowMapRef],
  );

  const rowRef = useMergedRefs(ref, onRowChange);

  const isRowSelected = row.getIsSelected();

  // Memoize visible cells to avoid recreating cell array on every render
  // Though TanStack returns new Cell wrappers, memoizing the array helps React's reconciliation
  const visibleCells = React.useMemo(
    () => row.getVisibleCells(),
    [row, columnVisibility, columnPinning],
  );

  return (
    <div
      key={row.id}
      role="row"
      aria-rowindex={virtualRowIndex + 2}
      aria-selected={isRowSelected}
      data-index={virtualRowIndex}
      data-slot="grid-row"
      tabIndex={-1}
      {...props}
      ref={rowRef}
      className={cn(
        "absolute flex w-full border-b [content-visibility:auto]",
        !adjustLayout && "will-change-transform",
        className,
      )}
      style={{
        height: `${getRowHeightValue(rowHeight)}px`,
        ...(adjustLayout
          ? { top: `${virtualItem.start}px` }
          : { transform: `translateY(${virtualItem.start}px)` }),
        ...style,
      }}
    >
      {visibleCells.map((cell, colIndex) => {
        const columnId = cell.column.id;

        const isCellFocused =
          focusedCell?.rowId === rowId && focusedCell?.columnId === columnId;
        const isCellEditing =
          editingCell?.rowId === rowId && editingCell?.columnId === columnId;
        const isCellSelected =
          cellSelectionKeys?.has(getCellKey(rowId, columnId)) ?? false;

        const isSearchMatch = searchMatchColumns?.has(columnId) ?? false;
        const isActiveSearchMatch = activeSearchMatch?.columnId === columnId;

        const nextCell = visibleCells[colIndex + 1];
        const isLastColumn = colIndex === visibleCells.length - 1;
        const { showEndBorder, showStartBorder } = getColumnBorderVisibility({
          column: cell.column,
          nextColumn: nextCell?.column,
          isLastColumn,
        });

        return (
          <div
            key={cell.id}
            role="gridcell"
            aria-colindex={colIndex + 1}
            data-slot="grid-cell"
            data-column-id={columnId}
            data-highlighted={isCellFocused ? "" : undefined}
            tabIndex={-1}
            className={cn({
              grow: stretchColumns && columnId !== "select",
              "border-e": showEndBorder && columnId !== "select",
              "border-s": showStartBorder && columnId !== "select",
            })}
            style={{
              ...getColumnPinningStyle({ column: cell.column, dir }),
              width: `calc(var(--col-${columnId}-size) * 1px)`,
            }}
          >
            {typeof cell.column.columnDef.header === "function" ? (
              <DataGridUtilityCell
                cell={cell}
                tableMeta={tableMeta}
                rowId={rowId}
                columnId={columnId}
                isFocused={isCellFocused}
                isRowSelected={isRowSelected}
              />
            ) : (
              <DataGridCell
                cell={cell}
                tableMeta={tableMeta}
                rowId={rowId}
                columnId={columnId}
                rowHeight={rowHeight}
                isFocused={isCellFocused}
                isEditing={isCellEditing}
                isSelected={isCellSelected}
                isSearchMatch={isSearchMatch}
                isActiveSearchMatch={isActiveSearchMatch}
                readOnly={readOnlyColumnIds.has(columnId)}
              />
            )}
          </div>
        );
      })}
    </div>
  );
}

interface DataGridUtilityCellProps<TData extends RowData> {
  cell: Cell<DataGridFeatures, TData>;
  tableMeta: DataGridTableMeta;
  rowId: string;
  columnId: string;
  isFocused: boolean;
  isRowSelected: boolean;
}

function DataGridUtilityCell<TData extends RowData>({
  cell,
  tableMeta,
  rowId,
  columnId,
  isFocused,
  isRowSelected,
}: DataGridUtilityCellProps<TData>) {
  const cellMapRef = tableMeta?.cellMapRef;

  const onCellChange = React.useCallback(
    (node: HTMLDivElement | null) => {
      if (!cellMapRef) return;

      const cellKey = getCellKey(rowId, columnId);

      if (node) {
        cellMapRef.current.set(cellKey, node);
      } else {
        cellMapRef.current.delete(cellKey);
      }
    },
    [rowId, columnId, cellMapRef],
  );

  return (
    <div
      data-slot="grid-utility-cell"
      data-focused={isFocused ? "" : undefined}
      tabIndex={-1}
      ref={onCellChange}
      className={cn("size-full px-3 py-1.5 outline-none", {
        "bg-primary/10": isRowSelected,
        "ring-1 ring-ring ring-inset": isFocused,
      })}
    >
      {flexRender(cell.column.columnDef.cell, cell.getContext())}
    </div>
  );
}

import { useValueAsRef } from "@base-ui/utils/useValueAsRef";
import { ChevronDownIcon, ChevronUpIcon, XIcon } from "lucide-react";
import * as React from "react";
import { Button, Input } from "uilab-core";
import { useDebouncedCallback } from "@/registry/base/hooks/use-debounced-callback";
import type { SearchState } from "@/registry/base/lib/data-grid-types";

function onTriggerPointerDown(event: React.PointerEvent<HTMLButtonElement>) {
  const target = event.target;
  if (!(target instanceof HTMLElement)) return;
  if (target.hasPointerCapture(event.pointerId)) {
    target.releasePointerCapture(event.pointerId);
  }

  // Prevent the trigger from stealing focus away from the input
  if (
    event.button === 0 &&
    event.ctrlKey === false &&
    event.pointerType === "mouse" &&
    !(event.target instanceof HTMLInputElement)
  ) {
    event.preventDefault();
  }
}

interface DataGridSearchProps extends SearchState {}

export const DataGridSearch = React.memo(DataGridSearchImpl, (prev, next) => {
  if (prev.searchOpen !== next.searchOpen) return false;

  if (!next.searchOpen) return true;

  // Exclude searchQuery because the input is uncontrolled, and hasQuery state handles the status text
  if (prev.matchIndex !== next.matchIndex) return false;

  if (prev.searchMatches.length !== next.searchMatches.length) return false;

  for (let i = 0; i < prev.searchMatches.length; i++) {
    const prevMatch = prev.searchMatches[i];
    const nextMatch = next.searchMatches[i];

    if (!prevMatch || !nextMatch) return false;

    if (
      prevMatch.rowId !== nextMatch.rowId ||
      prevMatch.columnId !== nextMatch.columnId
    ) {
      return false;
    }
  }

  return true;
});

function DataGridSearchImpl({
  searchMatches,
  matchIndex,
  searchOpen,
  onSearchOpenChange,
  searchQuery,
  onSearchQueryChange,
  onSearch,
  onNavigateToNextMatch,
  onNavigateToPrevMatch,
}: DataGridSearchProps) {
  const propsRef = useValueAsRef({
    onSearchOpenChange,
    onSearchQueryChange,
    onSearch,
    onNavigateToNextMatch,
    onNavigateToPrevMatch,
  });

  const inputRef = React.useRef<HTMLInputElement>(null);
  const isComposingRef = React.useRef(false);
  const [hasQuery, setHasQuery] = React.useState(searchQuery.length > 0);

  React.useEffect(() => {
    if (searchOpen) {
      requestAnimationFrame(() => {
        inputRef.current?.focus();
      });
      return;
    }

    isComposingRef.current = false;
    setHasQuery(false);
  }, [searchOpen]);

  React.useEffect(() => {
    if (!searchOpen) return;

    function onEscape(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.preventDefault();
        propsRef.current.onSearchOpenChange(false);
      }
    }

    document.addEventListener("keydown", onEscape);
    return () => document.removeEventListener("keydown", onEscape);
  }, [searchOpen, propsRef]);

  const debouncedSearch = useDebouncedCallback((query: string) => {
    propsRef.current.onSearch(query);
  }, 150);

  function onCompositionStart() {
    isComposingRef.current = true;
  }

  function onCompositionEnd(event: React.CompositionEvent<HTMLInputElement>) {
    isComposingRef.current = false;
    const value = event.currentTarget.value;
    setHasQuery(value.length > 0);
    propsRef.current.onSearchQueryChange(value);
    debouncedSearch(value);
  }

  function onKeyDown(event: React.KeyboardEvent) {
    event.stopPropagation();

    if (event.key === "Enter") {
      if (event.nativeEvent.isComposing) return;
      event.preventDefault();
      if (event.shiftKey) {
        propsRef.current.onNavigateToPrevMatch();
      } else {
        propsRef.current.onNavigateToNextMatch();
      }
    }
  }

  function onChange(event: React.ChangeEvent<HTMLInputElement>) {
    if (isComposingRef.current) return;
    const value = event.target.value;
    setHasQuery(value.length > 0);
    propsRef.current.onSearchQueryChange(value);
    debouncedSearch(value);
  }

  function onClose() {
    propsRef.current.onSearchOpenChange(false);
  }

  function onPrevMatch() {
    propsRef.current.onNavigateToPrevMatch();
  }

  function onNextMatch() {
    propsRef.current.onNavigateToNextMatch();
  }

  if (!searchOpen) return null;

  return (
    <div
      role="search"
      data-slot="grid-search"
      className="absolute inset-e-4 top-4 z-50 flex animate-in flex-col gap-2 rounded-lg border bg-background p-2 shadow-lg fade-in-0 slide-in-from-top-2"
    >
      <div className="flex items-center gap-2">
        <Input
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="off"
          spellCheck={false}
          placeholder="Find in table..."
          className="w-64"
          ref={inputRef}
          defaultValue={searchQuery}
          onChange={onChange}
          onKeyDown={onKeyDown}
          onCompositionStart={onCompositionStart}
          onCompositionEnd={onCompositionEnd}
        />
        <div className="flex items-center gap-1">
          <Button
            aria-label="Previous match"
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={onPrevMatch}
            onPointerDown={onTriggerPointerDown}
            disabled={searchMatches.length === 0}
          >
            <ChevronUpIcon />
          </Button>
          <Button
            aria-label="Next match"
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={onNextMatch}
            onPointerDown={onTriggerPointerDown}
            disabled={searchMatches.length === 0}
          >
            <ChevronDownIcon />
          </Button>
          <Button
            aria-label="Close search"
            variant="ghost"
            size="icon"
            className="size-7"
            onClick={onClose}
          >
            <XIcon />
          </Button>
        </div>
      </div>
      <div className="flex items-center gap-1 text-xs whitespace-nowrap text-muted-foreground">
        {searchMatches.length > 0 ? (
          <span>
            {matchIndex + 1} of {searchMatches.length}
          </span>
        ) : hasQuery ? (
          <span>No results</span>
        ) : (
          <span>Type to search</span>
        )}
      </div>
    </div>
  );
}

