  flexRender,
  getColumnBorderVisibility,
  getColumnPinningStyle,
} from "@/registry/base/lib/data-grid-utils";

const EMPTY_CELL_SELECTION_SET = new Set<string>();

interface DataGridProps<TData extends RowData>
  extends Omit<ReturnType<typeof useDataGrid<TData>>, "dir">,
    Omit<React.ComponentProps<"div">, "contextMenu"> {
  dir?: Direction;
  height?: number;
  stretchColumns?: boolean;
}

export function DataGrid<TData extends RowData>({
  dataGridRef,
  headerRef,
  rowMapRef,
  footerRef,
  dir = "ltr",
  table,
  tableMeta,
  virtualTotalSize,
  virtualItems,
  measureElement,
  columns,
  columnSizeVars,
  searchState,
  searchMatchesByRow,
  activeSearchMatch,
  cellSelectionMap,
  focusedCell,
  editingCell,
  readOnlyColumnIds,
  rowHeight,
  contextMenu,
  pasteDialog,
  onRowAdd: onRowAddProp,
  height = 600,
  stretchColumns = false,
  adjustLayout,
  className,
  ...props
}: DataGridProps<TData>) {
  const rows = table.getRowModel().rows;
  const readOnly = tableMeta?.readOnly ?? false;
  const columnVisibility = table.state.columnVisibility;
  const columnPinning = table.state.columnPinning;

  const onRowAddRef = useValueAsRef(onRowAddProp);

  const onRowAdd = React.useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      void onRowAddRef.current?.(event);
    },
    [onRowAddRef],
  );

  const onDataGridContextMenu = React.useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
    },
    [],
  );

  const onFooterCellKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (!onRowAddRef.current) return;

      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        void onRowAddRef.current();
      }
    },
    [onRowAddRef],
  );

  return (
    <div
      data-slot="grid-wrapper"
      dir={dir}
      {...props}
      className={cn("relative flex w-full flex-col", className)}
    >
      {searchState && <DataGridSearch {...searchState} />}
      <DataGridContextMenu
        tableMeta={tableMeta}
        columns={columns}
        contextMenu={contextMenu}
      />
      <DataGridPasteDialog tableMeta={tableMeta} pasteDialog={pasteDialog} />
      <div
        role="grid"
        aria-label="Data grid"
        aria-rowcount={rows.length + (onRowAddProp ? 1 : 0)}
        aria-colcount={columns.length}
        data-slot="grid"
        tabIndex={0}
        ref={dataGridRef}
        className="relative isolate grid overflow-auto rounded-md border select-none focus:outline-none"
        style={{
          ...columnSizeVars,
          maxHeight: `${height}px`,
        }}
        onContextMenu={onDataGridContextMenu}
      >
        <DataGridHeader
          table={table}
          tableState={table.state}
          rows={rows}
          headerRef={headerRef}
          dir={dir}
          stretchColumns={stretchColumns}
        />
        <div
          role="rowgroup"
          data-slot="grid-body"
          className="relative grid"
          style={{
            height: `${virtualTotalSize}px`,
            contain: adjustLayout ? "layout paint" : "strict",
          }}
        >
          {virtualItems.map((virtualItem) => {
            const row = rows[virtualItem.index];
            if (!row) return null;

            const cellSelectionKeys =
              cellSelectionMap?.get(row.id) ?? EMPTY_CELL_SELECTION_SET;

            const searchMatchColumns = searchMatchesByRow?.get(row.id) ?? null;
            const isActiveSearchRow = activeSearchMatch?.rowId === row.id;

            return (
              <DataGridRow
                key={row.id}
                row={row}
                tableMeta={tableMeta}
                rowMapRef={rowMapRef}
                virtualItem={virtualItem}
                measureElement={measureElement}
                rowHeight={rowHeight}
                columnVisibility={columnVisibility}
                columnPinning={columnPinning}
                focusedCell={focusedCell}
                editingCell={editingCell}
                cellSelectionKeys={cellSelectionKeys}
                searchMatchColumns={searchMatchColumns}
                activeSearchMatch={isActiveSearchRow ? activeSearchMatch : null}
                dir={dir}
                adjustLayout={adjustLayout}
                stretchColumns={stretchColumns}
                readOnlyColumnIds={readOnlyColumnIds}
              />
            );
          })}
        </div>
        {!readOnly && onRowAdd && (
          <div
            role="rowgroup"
            data-slot="grid-footer"
            ref={footerRef}
            className="sticky bottom-0 z-30 grid border-t bg-background"
          >
            <div
              role="row"
              aria-rowindex={rows.length + 2}
              data-slot="grid-add-row"
              tabIndex={-1}
              className="flex w-full"
            >
              <div
                role="gridcell"
                tabIndex={0}
                className="relative flex h-9 grow items-center bg-muted/30 transition-colors hover:bg-muted/50 focus:bg-muted/50 focus:outline-none"
                style={{
                  width: table.getTotalSize(),
                  minWidth: table.getTotalSize(),
                }}
                onClick={onRowAdd}
                onKeyDown={onFooterCellKeyDown}
              >
                <div className="sticky inset-s-0 flex items-center gap-2 px-3 text-muted-foreground">
                  <PlusIcon className="size-3.5" />
                  <span className="text-sm">Add row</span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

interface DataGridHeaderProps<TData extends RowData> {
  table: DataGridProps<TData>["table"];
  /** Only used to re-render when the table state changes. */
  tableState: DataGridProps<TData>["table"]["state"];
  /** Only used to re-render when the row model changes (select-all checkbox). */
  rows: unknown[];
  headerRef: DataGridProps<TData>["headerRef"];
  dir: Direction;
  stretchColumns: boolean;
}

// Memoized so scrolling, which re-renders `DataGrid` on every frame through the
// virtualizer, doesn't re-render every column header with its menu and tooltip.
const DataGridHeader = React.memo(
  DataGridHeaderImpl,
) as typeof DataGridHeaderImpl;

function DataGridHeaderImpl<TData extends RowData>({
  table,
  headerRef,
  dir,
  stretchColumns,
}: DataGridHeaderProps<TData>) {
  return (
    <div
      role="rowgroup"
      data-slot="grid-header"
      ref={headerRef}
      className="sticky top-0 z-30 grid border-b bg-background"
    >
      {table.getHeaderGroups().map((headerGroup, rowIndex) => (
        <div
          key={headerGroup.id}
          role="row"
          aria-rowindex={rowIndex + 1}
          data-slot="grid-header-row"
          tabIndex={-1}
          className="flex w-full"
        >
          {headerGroup.headers.map((header, colIndex) => {
            const sorting = table.state.sorting;
            const currentSort = sorting.find(
              (sort) => sort.id === header.column.id,
            );
            const isSortable = header.column.getCanSort();

            const nextHeader = headerGroup.headers[colIndex + 1];
            const isLastColumn = colIndex === headerGroup.headers.length - 1;

            const { showEndBorder, showStartBorder } =
              getColumnBorderVisibility({
                column: header.column,
                nextColumn: nextHeader?.column,
                isLastColumn,
              });

            const cornerClassName = cn(
              rowIndex === 0 && {
                "rounded-ss-[calc(var(--radius-md)-1px)]": colIndex === 0,
                "rounded-se-[calc(var(--radius-md)-1px)]": isLastColumn,
              },
            );

            return (
              <div
                key={header.id}
                role="columnheader"
                aria-colindex={colIndex + 1}
                aria-sort={
                  currentSort?.desc === false
                    ? "ascending"
                    : currentSort?.desc === true
                      ? "descending"
                      : isSortable
                        ? "none"
                        : undefined
                }
                data-slot="grid-header-cell"
                data-column-id={header.column.id}
                tabIndex={-1}
                className={cn("relative", {
                  grow: stretchColumns && header.column.id !== "select",
                  "border-e": showEndBorder && header.column.id !== "select",
                  "border-s": showStartBorder && header.column.id !== "select",
                })}
                style={{
                  ...getColumnPinningStyle({ column: header.column, dir }),
                  width: `calc(var(--header-${header.id}-size) * 1px)`,
                }}
              >
                {header.isPlaceholder ? null : typeof header.column.columnDef
                    .header === "function" ? (
                  <div
                    className={cn(
                      "size-full px-3 py-1.5 has-focus-visible:ring-1 has-focus-visible:ring-ring has-focus-visible:ring-inset",
                      cornerClassName,
                    )}
                  >
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext(),
                    )}
                  </div>
                ) : (
                  <DataGridColumnHeader
                    header={header}
                    table={table}
                    className={cornerClassName}
                  />
                )}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}

