const UNINITIALIZED = {};

function useRefWithInit<T>(init: () => T): React.RefObject<T> {
  const ref = React.useRef<T | typeof UNINITIALIZED>(UNINITIALIZED);

  if (ref.current === UNINITIALIZED) {
    ref.current = init();
  }

  return ref as React.RefObject<T>;
}

export { useRefWithInit };

import * as React from "react";

import { useIsomorphicLayoutEffect } from "@/registry/base/hooks/use-isomorphic-layout-effect";

function useValueAsRef<T>(value: T) {
  const ref = React.useRef<T>(value);

  useIsomorphicLayoutEffect(() => {
    ref.current = value;
  });

  return ref;
}

